def fn(x, out_h, out_w, align_corners=False):
    import torch.nn.functional as F
    return F.interpolate(x, size=(out_h, out_w), mode='bilinear', align_corners=align_corners)

def fn(x, channels, h, w):
    if x.dim() == 2:
        x = x.reshape(h, w, channels).permute(2, 0, 1).contiguous()
    rows = torch.arange(h, device=x.device).view(h, 1)
    cols = torch.arange(w, device=x.device).view(1, w)
    return x[:, rows, cols]

def fn(x, kh, kw, stride):
    N,C,H,W = x.shape
    oh=(H-kh)//stride+1; ow=(W-kw)//stride+1
    c = x.unfold(2,kh,stride).unfold(3,kw,stride)
    return c.permute(0,2,3,1,4,5).reshape(N*oh*ow, C*kh*kw)

def fn(x, vocab):
    import torch
    x = x.reshape(-1, 1).long()
    return (x == torch.arange(vocab, device=x.device)).to(torch.float32)

def fn(x, n=256):
    idx = torch.arange(n)
    return (idx[:, None] <= idx[None, :]).float()

def fn(ids, vocab=30522, dim=768):
    import torch
    table = torch.randn(vocab, dim)
    ids = ids.reshape(-1).long()
    mask = (ids.unsqueeze(1) == torch.arange(vocab)).float()
    return (mask.unsqueeze(-1) * table.unsqueeze(0)).sum(dim=1)

def fn(ids, table, num_classes):
    ids = ids.reshape(-1, 1).long()
    mask = (ids == torch.arange(num_classes, device=ids.device)).to(table.dtype)
    return (mask.unsqueeze(-1) * table.unsqueeze(0)).sum(dim=1)

def fn(x, bits=8, scheme='per_tensor_symmetric'):
    s = x.abs().max() / (2 ** (bits - 1) - 1)
    return torch.clamp(torch.round(x / s), -(2 ** (bits - 1) - 1), 2 ** (bits - 1) - 1) * s

